import { describe, expect, it } from 'vitest';
import { hasGeneratorHeader, headerLines } from './generator-marker.mjs';

describe('the header a known code generator writes', () => {
  it.each([
    '# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n',
    '# Generated by the gRPC Python protocol compiler plugin. DO NOT EDIT!\n"""Client."""\n',
    '# generated by datamodel-codegen:\n#   filename:  api.yaml\n',
    '# coding: utf-8\n\n"""\n    Petstore\n\n    The version: 1.0.0\n    Generated by OpenAPI Generator (https://openapi-generator.tech)\n"""\n',
    '/* tslint:disable */\n/**\n * Petstore\n *\n * NOTE: This class is auto generated by OpenAPI Generator (https://openapi-generator.tech).\n */\n',
    '// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n',
    '// @generated by protoc-gen-es v1.10.0 with parameter "target=ts"\n',
    '#\n# Autogenerated by Thrift Compiler (0.20.0)\n#\n',
  ])('is found in the leading comments or the module docstring: %j', (text) => {
    expect(hasGeneratorHeader(text)).toBe(true);
  });

  it.each([
    '"""Builds the auto-generated invoice numbers."""\n',
    '# DO NOT EDIT\n',
    '// @generated\n',
    '# Generated by Django 5.1 on 2026-01-01 10:00\n',
    'import os\n# generated by datamodel-codegen:\n',
    '"""Models."""\n"""Generated by OpenAPI Generator (https://openapi-generator.tech)"""\n',
  ])('is not a generic marker, a hand-edited migration or text below the header: %j', (text) => {
    expect(hasGeneratorHeader(text)).toBe(false);
  });

  it('reads the comment and docstring lines without their syntax', () => {
    expect(
      headerLines('#!/usr/bin/env python\n/* a\n * b */\nr"""c\nd"""  # e\nx = 1\n# f\n'),
    ).toEqual(['/usr/bin/env python', 'a', 'b', 'c', 'd']);
  });
});
